from pyspark.sql.functions import col, count, sum, when

def total_checks(results: list[dict[str, str]]) -> int:
    """Number of passed checks."""
    return sum(1 for r in results if r["status"] == "PASS")

def rename_columns(bronze_df, column_map: dict[str, str]):
    """Rename source columns to canonical names."""
    for src, tgt in column_map.items():
        bronze_df = bronze_df.withColumnRenamed(src, tgt)
    return bronze_df
